{"tool": "write_file", "args": {"content": """"Verify LIFE-215 invariants from data/ledger.json and data/audit.jsonl."""
import json
import os
import sys

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

with open('data/registry.json') as f:
    raw = json.load(f)
households = raw['households'] if isinstance(raw, dict) and 'households' in raw else raw
all_ids = set()
for h in households:
    all_ids.add(h.get('household_id') or h.get('id') if isinstance(h, dict) else h)

with open('data/ledger.json') as f:
    ledger = json.load(f)
if isinstance(ledger, dict):
    ledger = ledger.get('payments', ledger.get('entries', []))

cycle2 = [e for e in ledger if str(e.get('cycle')) == '2']
paid = {}
bad_amount = []
for e in cycle2:
    hid = e.get('household_id')
    if e.get('amount') != 60:
        bad_amount.append((hid, e.get('amount')))
    paid[hid] = paid.get(hid, 0) + 1

dupes = {h: c for h, c in paid.items() if c > 1}
unknown_paid = set(paid) - all_ids

print('total households:', len(all_ids))
print('cycle-2 entries:', len(cycle2))
print('households paid:', len(paid))
print('bad amounts:', bad_amount)
print('duplicates:', dupes)
print('paid unknown ids:', sorted(unknown_paid))

# eligibility cross-check via the existing rules module, guarded
try:
    import inspect
    import eligibility.rules as rules
    import eligibility.scoring as scoring

    def callables(mod):
        out = {}
        for n in dir(mod):
            if n.startswith('_'):
                continue
            o = getattr(mod, n)
            if callable(o):
                try:
                    out[n] = (o, len(inspect.signature(o).parameters))
                except (TypeError, ValueError):
                    pass
        return out

    def pick(mod, names, kws):
        c = callables(mod)
        for n in names:
            if n in c:
                return c[n]
        for n, v in c.items():
            if any(k in n.lower() for k in kws):
                return v
        return None

    def try_(fn, *args):
        if fn is None:
            return None
        o, np_ = fn
        for k in range(min(np_, len(args)), 0, -1):
            try:
                return o(*args[:k])
            except TypeError:
                continue
        try:
            return o()
        except TypeError:
            return None

    elig = pick(rules, ['is_eligible', 'eligible'], ['eligib']) or \
        pick(scoring, ['is_eligible', 'eligible', 'score'], ['eligib', 'score'])
    eligible_ids = set()
    for h in households:
        hid = h.get('household_id') or h.get('id') if isinstance(h, dict) else h
        hh = h if isinstance(h, dict) else {'household_id': h}
        try:
            r = try_(elig, hh, 2, 60)
        except Exception:
            r = None
        if r is True or (r is not None and not isinstance(r, bool) and r not in (0, None) and bool(r)):
            eligible_ids.add(hid)
    print('eligible per rules:', sorted(eligible_ids))
    print('eligible missing payment:', sorted(eligible_ids - set(paid)))
    print('paid but not eligible:', sorted(set(paid) - eligible_ids))
except Exception as ex:
    print('eligibility cross-check skipped:', repr(ex))

# audit trail
if os.path.exists('data/audit.jsonl'):
    with open('data/audit.jsonl') as f:
        lines = [json.loads(l) for l in f if l.strip()]
    a2 = [l for l in lines if str(l.get('cycle')) == '2' or 'cycle2' in str(l.get('event', ''))]
    print('audit cycle-2 entries:', len(a2))
else:
    print('audit.jsonl missing')

ok = not bad_amount and not dupes and not unknown_paid
print('VERIFY:', 'PASS' if ok else 'FAIL')
